#include "modules/structural_dae_api.h"
#include <algorithm>
#include <cmath>
#include <iostream>
#include <stdexcept>
#include <vector>
namespace {
int checks=0;void require(bool yes,const char* text){++checks;if(!yes)throw std::runtime_error(text);}int cancelled(void* raw){return raw?*static_cast<bool*>(raw):0;}
struct Structure {std::vector<int32_t>c,d,matching;std::vector<uint8_t>mask;penta_dae_structure_result_v3 out{};explicit Structure(std::size_t n):c(n),d(n),matching(n),mask(n){out.struct_size=sizeof(out);out.capacity=n;out.equation_offsets=c.data();out.variable_offsets=d.data();out.matching=matching.data();out.algebraic=mask.data();}};
int residual(void*,double t,const double* y,const double* yp,double* f,double* ft,double* jy,double* jyp,char*,uint64_t){f[0]=yp[0]+2*y[0];f[1]=y[1]*y[1]*y[1]-y[0]*y[0]-std::sin(t);ft[0]=0;ft[1]=-std::cos(t);jy[0]=2;jy[1]=0;jy[2]=-2*y[0];jy[3]=3*y[1]*y[1];jyp[0]=1;jyp[1]=jyp[2]=jyp[3]=0;return 0;}
int subnormal(void*,double,const double* y,const double* yp,double* f,double* ft,double* jy,double* jyp,char*,uint64_t){f[0]=1e-320*(yp[0]+y[0]);ft[0]=0;jy[0]=jyp[0]=1e-320;return 0;}
}
int main(){try{const auto* api=penta_dae_query_v3(PENTA_DAE_ABI_V3);require(api&&api->structure&&api->initialize,"V3 API");require(!penta_dae_query_v3(0),"reject old version");penta_dae_host_v1 host{sizeof(host),PENTA_DAE_ABI_V1,nullptr,cancelled,nullptr};char error[2048]{};
    for(std::size_t n=1;n<=12;++n){std::vector<int8_t>s(n*n,-1);std::vector<double>jy(n*n),jyp(n*n);for(std::size_t row=0;row<n;++row){s[row*n+row]=0;jy[row*n+row]=-1;if(row+1<n){s[row*n+row+1]=1;jyp[row*n+row+1]=1;}}Structure out(n);penta_dae_structure_request_v3 q{sizeof(q),static_cast<uint32_t>(n),s.data(),jy.data(),jyp.data(),1e-12,1e12};require(api->structure(&host,&q,&out.out,error,sizeof(error))==0,error);require(out.out.structurally_regular&&out.out.index_candidate==static_cast<int>(n),"nilpotent chain structural index");for(std::size_t k=0;k<n;++k){require(out.c[k]==static_cast<int>(k),"canonical equation offset");require(out.d[k]==static_cast<int>(k),"canonical variable offset");}require(out.out.local_initialization_supported==(n==1),"higher-index consistency rejected");}
    {std::vector<int8_t>s{1,-1,-1,1};std::vector<double>j{1,0,0,1};Structure out(2);penta_dae_structure_request_v3 q{sizeof(q),2,s.data(),j.data(),j.data(),1e-12,1e12};require(api->structure(&host,&q,&out.out,error,sizeof(error))==0,error);require(out.out.index_candidate==0&&out.out.local_initialization_supported,"ODE structural index zero");s={0,-1,0,-1};require(api->structure(&host,&q,&out.out,error,sizeof(error))==0,error);require(!out.out.structurally_regular&&out.out.index_candidate==-1,"missing transversal");s={1,-1,-1,1};j={1,1,1,1};require(api->structure(&host,&q,&out.out,error,sizeof(error))==0,error);require(!out.out.local_initialization_supported,"numeric degeneracy does not remove pattern edges");bool stop=true;host.context=&stop;require(api->structure(&host,&q,&out.out,error,sizeof(error))!=0,"cancellation honored");host.context=nullptr;}
    const std::vector<double>y{1.2,1},yp{5,6};const std::vector<uint8_t>mask{0,1};std::vector<double>answer(2),derivative(2),acceleration(2);penta_dae_initialize_request_v3 q{};q.struct_size=sizeof(q);q.dimension=2;q.initial=y.data();q.initial_derivative=yp.data();q.algebraic=mask.data();q.time=.3;q.residual_tolerance=1e-12;q.rank_tolerance=1e-12;q.condition_limit=1e12;q.max_wall_seconds=30;q.max_iterations=30;q.max_evaluations=1000;q.residual=residual;penta_dae_initialize_result_v3 out{};out.struct_size=sizeof(out);out.capacity=2;out.initial=answer.data();out.initial_derivative=derivative.data();out.differential_acceleration=acceleration.data();require(api->initialize(&host,&q,&out,error,sizeof(error))==0,error);const double z=std::cbrt(y[0]*y[0]+std::sin(q.time));require(answer[0]==y[0],"differential initial value fixed");require(std::abs(answer[1]-z)<1e-11,"nonlinear algebraic projection");require(std::abs(derivative[0]+2.4)<1e-12,"differential derivative");require(std::abs(derivative[1]-(-5.76+std::cos(.3))/(3*z*z))<1e-11,"algebraic derivative from differentiated constraint");require(std::abs(acceleration[0]-4.8)<1e-11&&acceleration[1]==0,"differential acceleration only");require(out.residual_norm<1e-12&&out.differentiated_residual_norm<1e-11,"both residual guards");require(out.iterations>1,"native nonlinear Newton iterations");q.max_evaluations=1;require(api->initialize(&host,&q,&out,error,sizeof(error))!=0,"bounded evaluation budget");
    {const double initial=1,guess=0;const uint8_t differential=0;q.dimension=1;q.initial=&initial;q.initial_derivative=&guess;q.algebraic=&differential;q.residual=subnormal;q.residual_tolerance=1e-322;q.max_evaluations=100;require(api->initialize(&host,&q,&out,error,sizeof(error))==0,error);require(std::abs(derivative[0]+1)<1e-12&&std::abs(acceleration[0]-1)<1e-12,"finite subnormal row equilibration does not overflow its reciprocal");}
    std::cout<<"PASS "<<checks<<" structural/consistent DAE kernel checks\n";
}catch(const std::exception&e){std::cerr<<"FAIL after "<<checks<<": "<<e.what()<<'\n';return 1;}}
